		description: '轻型制导导弹是很多新手飞行员入门的第一款制导导弹。它在同类武器中性能欠佳但胜在便宜。成本低廉、价格便宜而且简单易用，它最大的优势就是能显著提升新兵战斗力。nn它的制导系统就是一种简易的单向信道，发射平台经此不断向导弹传输目标的实时位置信息。相对的，该系统很容易被干扰，而且所使用的热成像探头非常原始，这使得它难以对付装备有诱饵弹的灵活目标。由于采用了各种节省成本的手段，轻型制导导弹Mk1的穿甲能力很弱。不过，要是成功透过了装甲，该导弹原本针对深空采矿设计的弹头也能能造成高效杀伤。',
