		id: 'weapon_gen_m_gatling_01_mk1',
		version: 0,
		name: 'M 闪电连射炮 Mk1',
		description: '闪电连射炮中规中矩的伤害输出和冷却效能使其成为选择困难症的战斗飞行员的绝佳之选。它通常被认为是熟悉脉冲激光之后的下一步选择。它较长的连射时间使其足以撕裂任何同级目标，但是由于射弹更大，它的弹速慢于脉冲激光。因此使用者需要自行安排开火时机和武器冷却。对上该武器时，灵活的飞船可以通过平移和螺旋机动规避火力。面对主力舰，闪电连射炮适合用于摧毁诸如炮塔和护盾等表面部件，但是其对船体作用有限。nn今天的闪电连射炮是Argon军方科学家在以前的质量加速器基础之上发展而来的。质量加速器是一种早在Kha\'ak危机时期就投入使用的武器。他们放弃了原武器穿透护盾的能力，转而尽力提升其连续射弹的威力，最终结果就是这个可靠的通用型武器，因其纯粹的实用性而很快就被联邦的盟友们采纳。Mk2型采用了更大的射弹并且保持了相同的弹速，射速更低但是总体伤害提升。',
