		description: '光束发射器是针对性的反战斗机武器，以其高精准度闻名。它发射的高速光束几乎能瞬间击中目标。然而，有点儿违反直觉，它的瞬发精准度是通过限制能量输出的方式实现的。由于光束不如许多同类武器发射的射弹那样强力，它只能通过持续照射来造成伤害，这将飞行员暴露在被反击的风险下。因此，光束发射器一般装备在灵活的战斗机上，因为它们才有能力和目标贴身肉搏并在必要时通过机动拉开距离。nnMk2型尝试提高光束的能量密度以弥补伤害上的不足，代价是武器更容易过热。',
