		name: 'S 等离子加农炮 Mk1',
		description: '等离子加农炮集高伤害和远射程于一身。它的缺点是弹速慢且过热快，这使其命中率就像伤害一样离谱。因此它的主要应用情景就是装备到战斗机群上用于有效杀伤主力舰。和霰弹炮或Split钛加速器这些用于从盲区攻击的短距武器不同，等离子加农炮虽然伤害略低但是强在射程超长。技术高超的飞行员甚至可以通过预判或近身用它有效击落小型目标，他们同时也能规避这样的攻击。nn等离子加农炮是在Paranid内战初期，由教皇圣教团在高能等离子投射器的基础之上开发出来的。和它的前身一样，等离子加农炮同样存在残余辐射大量累积的问题，这些辐射必须在两次发射间隙被完全清除掉，否则就会损害武器自身。Argon特勤部门窃取了该武器的蓝图。Argon联邦参战后将之在联合体内部公之于众。nnMk2型有更高的射速、更低的热量积累以及更高的伤害输出。',
