		description: '顾名思义，霰弹炮用对船体和护盾的高伤害弥补了有效射程的不足。原理上，它和其前身闪电连射炮非常相似。不同的是，同时发射多个射弹需要大的枪管口径，更大的发射间隔，因而耗费更多能量。在伤害输出上，霰弹炮堪比等离子加农炮，但是两者的用处有所不同。有经验的战斗飞行员有时会用该武器对付小型目标以尽快结束战斗，不过通常认为应该尽量避免此种情形。霰弹炮在对上像M级飞船这样的大型慢速目标上才能发挥出全部实力，因为这些目标无法轻易地躲避其射弹。它对主力舰的表面部件也非常有效，只要飞行员能找机会在炮塔盲区抵近射击。nnMk2型发射的弹片数量少一些，但是弹速和射速都更快。因此其整体伤害输出和武器精准度都有所提升。',
