		name: 'PAR M 质量加速器 Mk1',
		description: '质量加速器发射单枚能在很长的距离上保持精准度和威力的高能射弹。热量累积几乎在按下开火键的瞬间发生，之后飞行员可仔细瞄准后择机放开开火键以击发武器。这种独特能力的代价是：武器固定为轴向，无法自行转动，因此飞行员必须完全依靠调整自身飞船姿态来瞄准。虽然长时间内的武器输出数据可能不太好看，但是它的强大之处在于先手爆发能力。它能攻其不备，在缠斗开始前就抢先摧毁关键部件。因此强烈推荐在混编舰队中使用它，比如支援正在作战的部队。能够和敌人保持距离的高速机动飞船也可利用该武器的射程优势放敌人风筝。nn该武器不可与星门关闭前的同名武器混淆，那种武器通过连续发射可透过护盾的射弹来杀伤敌人。Argon联邦和Paranid神界的军方都想尝试改进这种旧武器，并且两者都在此基础上开发出了相较于原型面貌全非的新武器。Paranid选择的路线是双轨轨道炮，炮管上排列着精确调教同步的超导电磁体。奇怪的是，对于这种全新类型的武器，Trinity Sanctum | 三圣殿 的专家们竟然选择了沿用其前身的命名。nnMk2型选用了昂贵且精确校准的电磁体，大幅降低了武器每发蓄能产生的热量。',
