		name: 'TEL 凤凰主炮',
		description: '考虑到凤凰级驱逐舰"借鉴"了Argon和Paranid技术，它的主炮神似Argon巨兽就完全不奇怪了。nn有人指责说凤凰窃取并抄袭了巨兽主炮的技术，不过他们很快就因为诽谤Teladi公司而遭到法庭传唤。质疑该判决的理由之一是和巨兽相似的三炮管设计。凤凰主炮在之后的一次版本迭代中悄悄更改了这一设计，遭到追问后官方给出的理由是过高的能量消耗和散热能力不足。nn我们确定两者相似的三炮管设计以及能耗和装弹指标只是纯粹的巧合。',
