		version: 1,
		name: 'ATF XL级主炮',
		description: '当迭戈·金城博士第一次提出用聚变光束炮作为阿斯加德XL级主炮的想法时，人们觉得他疯了。即使在ATF极端军事化的研究所里，能蒸发空间站的"超级巨炮"也被认为是可笑离谱的想法，主要原因是光是建造一台原型机的花费就足够造出一整只装备齐全的驱逐舰舰队了。nn事情本该以金城博士的失踪而告结，直到几年后原型机和蓝图被一并送到了ATF总部。虽然显然有某位神秘的金主赞助了金城博士的工作，但是直到今天也无人站出来声称对此负责。nn金城博士也再也没有出现过。小道消息说他的知识太宝贵以致于绝不能落入敌手，故他本人很可能被拘留在什么地方或是被灭口了。',
