		description: '稳、准、狠。nnTerran主炮最特别的地方在于它可以安装在多种飞船上，并且强大到足以扭转战局。nn有人认为这种高射速质子火力网是极端进攻性的武器，只应该被用在最激烈的作战行动中。nn多次有人提出应该从法律上限制Terran主炮的应用场景。然而，即使只是与之相关的外交对话尝试都被Terran高层一口回绝。',
