		version: 1,
		name: 'TER M 介子流 Mk1',
		description: '介子流是一款极为强大且非常昂贵的武器。它射出并短暂维持一束几乎能瞬间击中目标的光束。就像其它高精度武器一样，该武器无法自动追踪目标，完全依赖于飞行员的瞄准能力。在其他方面，包括不太出众射程，它操作起来更像光束武器，例如光束发射器。介子流不需要充能，原则上可以按住开火键持续发射。但是，飞船的热量槽通常无法支持你这么做。由于该型武器恐怖的能耗和发热，它只能装在高能武器槽。nn由于各种原因，Terran军事部门一直以来都在尝试研发超大型的激光炮。即使需要全新的专用平台，即使能效比低到令人发指，这种武器的潜在威慑力却是不容置疑的。而且，超级武器在Terran人心中有着特殊的地位。因此，当听说它的小型原型机要开始开发时，该项目得到了公众的强烈支持。万众瞩目之下，介子流的出现意味着保护国在实现Terran梦的漫漫长征路上迈出了谨慎而坚定的第一步。nn以大幅增加材料成本为代价，Mk2型的伤害更上一层楼。',
