		description: '虽然名字和星门网络中最常见的武器相同，Terran脉冲激光的工作方式其实有所不同。它摒弃了使用弹夹的爆发式连射模式，转而致力于提高单发威力。虽然射程有所降低，它将粒子加速到更高的速度以更快到达目标。因此和非Terran的同名武器相比，它的发热更高。不过得益于其极端高效的运作方式，它几乎不会出现武器过热。因此，使用该版本脉冲激光的飞行员仍然能通过咬住目标进行持续火力输出以最大化其伤害效能。nn星门重组后，Terran保护国迅速调查了星门网络中潜在对手的军事实力，很快就弄到了当时最常见的武器——脉冲激光——的蓝图。注意到它灵活性和优美的简洁性之后，Terran强大的军工机器立刻全速运转起来：大幅改进有潜力的技术使其变成Terran风格并且阻止逆向工程。最终的成品实际上仍然和脉冲激光差不多。虽然最初认为境外势力无法使用它，但是出乎意料的，该型脉冲激光只需要微小的改动就能装备到许多其它飞船上。nnMk2型只增加了一点点热积累速率，却大幅提升了武器的能量输出和射速。',
