		description: '妖王大型炮塔发射一种由专用脉冲激光加速的高温高速弹丸。通常情况下，前置固定式武器往往比同级别的炮塔版本性能更佳、威力更大，但妖王的炮塔却是罕见的例外；在近距离上，这种炮塔的威力比肩甚至超过大型脉冲激光武器。然而随着发射距离的增加，其威力断崖式衰减，以至于在最大射程处，威力勉强与大型脉冲激光炮塔相当。虽然妖王在远距离攻击下自保完全没问题，不过得益于炮塔在近距离上高杀伤的特性，它在近距离战斗中才最为凶残，这使得妖王和战斗风格激进的舰长相性最佳。这种出众的战斗效能源于妖王的能源核心，也就是炮塔输出能量之来源。nn博索塔评论说，该炮塔采用了电子冗余的设计，使其在面对内部辐射带来的损伤时具有极佳的鲁棒性。虽然剂量不大，但是该炮塔会持续暴露在能源核心的辐射之下，因此这些设计是绝对必要的。',
