		version: 1,
		name: 'BOR L 离子网发射器 Mk1',
		description: '离子网发射器是以实验型技术闻名的政府机构，Boron皇家防御军事研究所，开发的功能性装备。该发射器爆发式射出一系列会自动在预估的目标位置爆炸的高速射弹。每次爆炸会生成一个大型网状结构，舰船触碰到后移动能力会受到影响。虽然该网状结构能同时有效作用于多个目标，但是在近距离缠斗中表现不佳，因为友方舰船同样会受到影响。军事上该特性限制了它在某些舰队组成中的应用，民用上大部分需要在偏远星系作业的飞船又无法适配该炮塔。',
