		description: '现代高射炮塔技术在星门网络中还不太普及，因此拥有该技术的势力都极力保密。由于是范围伤害，该武器在近距离上非常强力，尤其是针对战斗机。nnL级Boron高射炮塔遵循Boron一贯的武器设计思路，对盾特攻但对船体乏力。不管是否命中物体，该炮塔射弹都设定为在预设目标位置引爆。该特性使得目标即使恰巧躲过射弹，也会被其爆炸波及造成有效杀伤。',
